def build_book2():
    title = "No Blue Sky: The Oxygen Gamble"
    subtitle = "A novel of Mars, sovereignty, and the birth of a civilization"

    chapter_entries = [(f"Chapter {n} &mdash; {t}", n) for n, t in BOOK2_CHAPTERS_ORIG]

    parts = [
        html_header(title, STYLE),
        title_page("Book II", title, subtitle),
        copyright_page(),
        toc_page(chapter_entries),
    ]

    for num, title in BOOK2_CHAPTERS_ORIG:
        parts.append(build_book2_chapter(num, title))

    parts.append(about_author())
    parts.append(series_page())
    parts.append(html_footer())

    return '\n'.join(parts)


