# INTERSTITIAL CHAPTERS (Earth/Mars parallel narratives)
# ────────────────────────────────────────────────────────────
def build_interstitial_chapter(num, title, book_id):
    """Chapters that connect the Moon base story to the Mars/Earth political saga"""
    content = []
    content.append(chapter_h1(num, title))

    if "Treaty Debate" in title:
        content.append(epigraph('Mission AI: "While the pioneers build their home on the Moon, Earth debates whether to let them keep it."'))
        content.append(epigraph('Ambassador Okonkwo: "The Artemis Accords were supposed to be about cooperation. Now they\'re about control."'))
        content.append(p('On Earth, in the marble halls of Geneva, a very different kind of battle was being fought. The Treaty of Tharsis — named for the massive volcanic plateau on Mars where the first permanent settlement had taken root — was supposed to formalize the relationship between Earth and its off-world colonies. Instead, it had become a flashpoint for every unresolved tension between the old world and the new.'))
        content.append(p('Ambassador Sarah Okonkwo represented Martian interests in the negotiations, a position that had evolved from supplicant to advocate to equal over the course of fifty years. She had been born on Earth but had spent most of her adult life on Mars, and she understood both sides in a way that few could. That understanding made her invaluable — and deeply suspicious to both factions.'))
        content.append(p('"The treaty as written," she told the assembly, "gives Earth veto power over Martian resource development, limits Martian technological autonomy, and subjects Martian citizens to Terran courts in all matters involving Earth nationals. This is not a partnership. This is colonialism with a diplomatic veneer."'))
        content.append(p('The Earth delegates shifted uncomfortably. They had expected gratitude, not resistance. But Sarah had learned on Mars that survival depended on clear vision and firm boundaries — lessons that served as well in diplomacy as they did in dome maintenance.'))
        content.append(p('As the debate continued through days and then weeks, the fate of interplanetary relations hung in the balance. And on the Moon, the pioneers continued their work, unaware that the political future of their entire endeavor was being decided by people who had never worn a spacesuit or felt the vacuum of space against their visor.'))

    elif "Martian Independence" in title:
        content.append(epigraph('Mission AI: "While the Moon base grows, Mars prepares to declare itself a nation."'))
        content.append(epigraph('Chancellor Varga: "We did not cross the void to remain subjects."'))
        content.append(p('In the Valles Marineris Colonial Council chamber, Kaito Varga addressed the assembled representatives. The atmosphere was electric with the gravity of the moment — not the simulated gravity of the habitat\'s rotating sections, but the weight of history pressing down on every decision.'))
        content.append(p('"Fifty years ago," he began, "our grandparents landed on this world with nothing but hope and the contents of three cargo ships. They survived the first winter by sharing rations, by working shifts that lasted sixteen hours, by refusing to let the cold and the dark break their spirits. They didn\'t ask Earth for permission to survive. They simply survived."'))
        content.append(p('He paused, letting the words settle over the chamber. "Now it\'s our turn. We don\'t ask Earth for permission to govern ourselves. We simply govern."'))
        content.append(p('The debate that followed was fierce, but the outcome was never really in doubt. The Martian Declaration of Self-Governance passed with overwhelming support, and the news was transmitted to Earth through quantum channels that no Terran authority could monitor or block. On the Moon, the base received the news with a mixture of pride and concern — their fates were now linked to Mars in ways that the Artemis Accords had never anticipated.'))

    elif "Declaration" in title:
        content.append(epigraph('Mission AI: "A declaration is words on paper. What comes after is written in blood and oxygen."'))
        content.append(epigraph('Chancellor Varga: "Now we find out who our friends are."'))
        content.append(p('The response from Earth was not immediate. For three days, the quantum channels carried nothing but silence — a silence that felt more threatening than any ultimatum. On the fourth day, the transmission arrived, and it was exactly what the Martian council had feared.'))
        content.append(p('Earth did not recognize the Declaration of Self-Governance. The Terran Diplomatic Corps issued a formal statement declaring the Martian action "null and void under international law" and warning that "consequences would follow." The precise nature of those consequences was left unspecified, which made them more menacing rather than less.'))
