def extract_chapters(html):
    """Extract chapters from original HTML"""
    # Split by chapter headings
    pattern = re.compile(r'(<(?:h[12])>.*?Chapter\s+\d+.*?</(?:h[12])>)', re.DOTALL)
    parts = pattern.split(html)

    chapters = []
    for i, part in enumerate(parts):
        if re.match(r'<(?:h[12])>.*?Chapter\s+\d+', part):
            ch_title = re.sub(r'<[^>]+>', '', part).strip()
            ch_num_match = re.search(r'Chapter\s+(\d+)', ch_title)
            ch_num = int(ch_num_match.group(1)) if ch_num_match else 0
            # Content starts here but continues until next chapter
            # The split gives: [before, heading, content_until_next_heading, heading, ...]
            # So the content is at index i+1
            content = ""
            if i + 1 < len(parts):
                content = parts[i + 1]
                # Remove up to the next heading
                content = re.sub(r'<(?:h[12])>.*?Chapter\s+\d+.*$', '', content, flags=re.DOTALL)
            chapters.append((ch_num, ch_title, content.strip()))
    return chapters

