body { font-family: Georgia, 'Times New Roman', serif; line-height: 1.5; font-size: 11pt; color: #000; widows: 2; orphans: 2; margin: 0; padding: 0; }
.title-page { text-align: center; padding-top: 28%; page-break-after: always; }
