h2 { text-align: center; font-family: 'Helvetica Neue', Arial, sans-serif; font-size: 13pt; font-weight: bold; page-break-before: always; margin: 3.5em 0 1.2em 0; }
p { margin: 0.15em 0; text-indent: 0.2in; text-align: justify; widows: 2; orphans: 2; }
h1 + p, h2 + p, h1 + .epigraph, h2 + .epigraph { text-indent: 0; }
p.epigraph { text-align: center; font-style: italic; color: #555; text-indent: 0; margin: 1em 1.5em; font-size: 10pt; }
