.series-page { page-break-before: always; padding-top: 25%; text-align: center; font-size: 11pt; }
.series-page h2 { text-align: center; font-size: 14pt; page-break-before: avoid; margin-bottom: 1em; }
.series-page p { text-indent: 0; margin: 0.3em 0; }"""

def P(t): return '<p>' + t + '</p>'
def EP(t): return '<p class="epigraph">' + t + '</p>'
def ch_h2(n, t): return '<h2>Chapter ' + str(n) + ' &mdash; ' + t + '</h2>'
def ch_h1(n, t): return '<h1>Chapter ' + str(n) + ' &mdash; ' + t + '</h1>'

def header(title):
