'''

def footer():
    return '\n</body>\n</html>'

def title_page(label, title, sub):
    return '<div class="title-page">\n  <p class="series-name">No Blue Sky Series &#8226; ' + label + '</p>\n  <h1 class="book-title">' + title + '</h1>\n  <p class="subtitle">' + sub + '</p>\n  <p class="author">by Bob Mills</p>\n</div>\n'

def copyright_page():
    return '<div class="copyright-page">\n  <p><strong>Copyright &copy; 2026 by Bob Mills</strong></p>\n  <p>All rights reserved. No part of this publication may be reproduced, distributed, or transmitted in any form or by any means, including photocopying, recording, or other electronic or mechanical methods, without the prior written permission of the publisher, except in the case of brief quotations embodied in critical reviews and certain other noncommercial uses permitted by copyright law.</p>\n  <p>This is a work of fiction. Names, characters, places, and incidents either are the product of the author&#8217;s imagination or are used fictitiously. Any resemblance to actual persons, living or dead, events, or locales is entirely coincidental.</p>\n  <p class="publisher-name">Self-Published</p>\n</div>\n'

def toc_page(entries):
    rows = '\n'.join(['<tr><td class="toc-chapter">' + l + '</td><td class="toc-page-num">' + str(p) + '</td></tr>' for l, p in entries])
    return '<div class="toc-page">\n  <h1>Contents</h1>\n  <table class="toc-table">\n  ' + rows + '\n  </table>\n</div>\n'

def about_author():
    return '<div class="about-author">\n  <h2>About the Author</h2>\n  <p>Bob Mills is a writer of science fiction and speculative fiction, exploring the intersections of technology, society, and the human spirit. The No Blue Sky series represents his ongoing exploration of what it means to build a civilization beyond Earth.</p>\n  <p>Bob lives and writes in the Pacific Northwest, where the rain provides ample time for imagining the wide-open spaces of other worlds.</p>\n</div>\n'

def series_page():
    return '<div class="series-page">\n  <h2>The No Blue Sky Series</h2>\n  <p><strong>Book I:</strong> Built from Dust</p>\n  <p><strong>Book II:</strong> The Oxygen Gamble</p>\n  <p><strong>Book III:</strong> Rivers Under Mars</p>\n  <p><strong>Book IV:</strong> The Red Charter</p>\n  <p><strong>Book V:</strong> The First Martian Nation</p>\n</div>\n'

def count_words(text):
    clean = re.sub(r'<[^>]+>', '', text)
    clean = re.sub(r'&[a-z]+;', ' ', clean)
    return len(clean.split())

# ────────────────────────────────────────────────────────────
