def build_book2():
    toc = [(f"Chapter {n} &mdash; {t}", n - 20) for n, t, _ in BOOK2_CHAPTERS]
    parts = [
        header("No Blue Sky: The Oxygen Gamble"),
        title_page("Book II", "No Blue Sky: The Oxygen Gamble", "A novel of Mars, sovereignty, and the birth of a civilization"),
        copyright_page(),
        toc_page(toc),
    ]
    for _, _, builder in BOOK2_CHAPTERS:
        parts.append(builder())
    parts += [about_author(), series_page(), footer()]
    return '\n'.join(parts)

