def main():
    print("=" * 60)
    print("NO BLUE SKY SERIES REFLOW")
    print("=" * 60)

    os.makedirs(f"{BASE}/Book_II_The_Oxygen_Gamble", exist_ok=True)
    os.makedirs(f"{BASE}/Book_IV_The_Red_Charter", exist_ok=True)
    os.makedirs(f"{BASE}/Book_V_The_First_Martian_Nation", exist_ok=True)

    results = []

    for label, builder, path in [
        ("Book 2: The Oxygen Gamble", build_book2, f"{BASE}/Book_II_The_Oxygen_Gamble/No_Blue_Sky_2_The_Oxygen_Gamble.html"),
        ("Book 4: The Red Charter", build_book4, f"{BASE}/Book_IV_The_Red_Charter/No_Blue_Sky_4_The_Red_Charter.html"),
        ("Book 5: The First Martian Nation", build_book5, f"{BASE}/Book_V_The_First_Martian_Nation/No_Blue_Sky_5_The_First_Martian_Nation.html"),
    ]:
        print(f"\nBuilding {label}...")
        content = builder()
        wc = count_words(content)
        with open(path, 'w') as f:
            f.write(content)
        print(f"  -> {wc} words ({wc/220:.0f} pages)")
        results.append((label, wc))

    print("\n" + "=" * 60)
    print("SUMMARY")
    print("=" * 60)
    total = 0
    for label, wc in results:
        pages = wc / 220
        status = "OK" if 180 <= pages <= 220 else ("SHORT" if pages < 180 else "LONG")
        print(f"  {label:<40s} {wc:>6d} words ({pages:.0f} pages) [{status}]")
        total += wc
    print(f"  {'TOTAL':<40s} {total:>6d} words ({total/220:.0f} pages)")
    print()

    with open(f"{BASE}/reflow_manifest.txt", 'w') as f:
        f.write("No Blue Sky Reflow Results\n")
        f.write("=" * 50 + "\n")
        for label, wc in results:
            f.write(f"{label}: {wc} words\n")
        f.write(f"Total: {total} words\n")

